types=json.loads((q/'resolved-type-schema.json').read_text());cat=next(t for t in types if t['name']=='Cat');fields={f['name']:f['native_offset'] for f in cat['fields']};assert fields['Damage']==80 and fields['CriDmg']==112 and fields['CriPer']==160
assert struct.unpack_from('<f',native,raw(0x106c268))[0]==struct.unpack('<f',struct.pack('<f',.001))[0]
